package com.diyalamp.desktop;

import javax.swing.*;
import javax.swing.event.*;
import javax.swing.text.*;
import javax.swing.undo.UndoManager;
import java.awt.*;
import java.awt.datatransfer.*;
import java.awt.event.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.prefs.Preferences;

public final class Diyalamp {
    public static final String VERSION="1.0.0";
    private final JFrame frame=new JFrame("diyalamp");
    private NoteStore store;
    private final Preferences preferences=Preferences.userRoot().node("com/diyalamp/desktop");
    private final Map<Path,Session> sessions=new LinkedHashMap<>();
    private final DefaultListModel<Path> files=new DefaultListModel<>();
    private final JList<Path> sidebar=new JList<>(files);
    private final JTextField search=new JTextField();
    private final JLabel folderName=new JLabel(),status=new JLabel("All changes saved"),count=new JLabel(" ");
    private final JTabbedPane left=new JTabbedPane(),right=new JTabbedPane();
    private final JPanel pages=new JPanel(new BorderLayout()),library=new JPanel(new BorderLayout());
    private final JSplitPane layout=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT);
    private JSplitPane split;
    private WritingPane active;
    private NoteStore.Deleted lastDeleted;
    private boolean refreshing;
    private final javax.swing.Timer autosave=new javax.swing.Timer(650,e->saveAll(false));

    private static final class NoteIcon implements Icon {public int getIconWidth(){return 14;}public int getIconHeight(){return 16;}public void paintIcon(Component c,Graphics g,int x,int y){Graphics2D a=(Graphics2D)g.create();a.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);a.setColor(Theme.MUTED);a.drawRoundRect(x+1,y+1,10,13,2,2);a.drawLine(x+4,y+5,x+8,y+5);a.drawLine(x+4,y+8,x+8,y+8);a.dispose();}}
    private static final class Session {
        Path path;String fingerprint;final DefaultStyledDocument document;final UndoManager undo=new UndoManager();boolean dirty,error;int loadingViews,viewCount;String serialized;
        Session(Path path,NoteStore.Loaded loaded){this.path=path;fingerprint=loaded.fingerprint();document=Markdown.read(loaded.text());serialized=Markdown.write(document);document.addUndoableEditListener(undo);}
    }
    public static void main(String[] args){Theme.setup();Path requested=args.length==2&&args[0].equals("--workspace")?Path.of(args[1]):null;SwingUtilities.invokeLater(()->{try{new Diyalamp(requested);}catch(Exception e){JOptionPane.showMessageDialog(null,e.getMessage(),"diyalamp could not open",JOptionPane.ERROR_MESSAGE);}});}
    private Diyalamp(Path requested)throws IOException {
        frame.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);frame.setMinimumSize(new Dimension(820,560));frame.setSize(1180,800);frame.setLocationRelativeTo(null);ImageIcon lamp=Theme.lamp(128);if(lamp!=null)frame.setIconImage(lamp.getImage());
        frame.getRootPane().putClientProperty("apple.awt.fullWindowContent",false);
        buildLibrary();buildPages();layout.setLeftComponent(library);layout.setRightComponent(pages);layout.setDividerLocation(230);layout.setDividerSize(1);layout.setBorder(null);frame.add(layout);frame.setJMenuBar(menu());
        frame.addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){if(saveAll(true)){autosave.stop();frame.dispose();}}});
        if(Desktop.isDesktopSupported()){Desktop desktop=Desktop.getDesktop();if(desktop.isSupported(Desktop.Action.APP_QUIT_HANDLER))desktop.setQuitHandler((e,response)->{if(saveAll(true))response.performQuit();else response.cancelQuit();});if(desktop.isSupported(Desktop.Action.APP_ABOUT))desktop.setAboutHandler(e->about());}
        Path folder=requested!=null?requested:Path.of(preferences.get("folder",Path.of(System.getProperty("user.home"),"Documents","diyalamp").toString()));
        setFolder(folder);if(store.notes().isEmpty())store.create("Welcome to diyalamp",welcome());refresh();if(!files.isEmpty())open(files.firstElement(),false);frame.setVisible(true);autosave.start();
    }
    private void buildLibrary(){library.setBackground(Theme.SIDEBAR);library.setBorder(BorderFactory.createEmptyBorder(16,12,12,12));JPanel top=new JPanel();top.setOpaque(false);top.setLayout(new BoxLayout(top,BoxLayout.Y_AXIS));JLabel brand=new JLabel("diyalamp",Theme.lamp(24),JLabel.LEFT);brand.setFont(Theme.font(18).deriveFont(Font.BOLD));brand.setBorder(BorderFactory.createEmptyBorder(0,4,20,0));top.add(brand);folderName.setForeground(Theme.MUTED);folderName.setBorder(BorderFactory.createEmptyBorder(0,4,12,0));top.add(folderName);search.putClientProperty("JTextField.placeholderText","Find a note…");search.getAccessibleContext().setAccessibleName("Find a note by name");search.setMaximumSize(new Dimension(Integer.MAX_VALUE,36));top.add(search);top.add(Box.createVerticalStrut(12));JButton create=Theme.button("New note  +",this::newNote);create.setBackground(Theme.RED);create.setForeground(Color.WHITE);create.setAlignmentX(Component.LEFT_ALIGNMENT);create.setMaximumSize(new Dimension(Integer.MAX_VALUE,36));top.add(create);top.add(Box.createVerticalStrut(16));library.add(top,BorderLayout.NORTH);
        sidebar.setCellRenderer(new DefaultListCellRenderer(){public Component getListCellRendererComponent(JList<?> list,Object value,int index,boolean selected,boolean focus){JLabel l=(JLabel)super.getListCellRendererComponent(list,value,index,selected,focus);Path p=(Path)value;l.setIcon(new NoteIcon());l.setIconTextGap(8);l.setText((store==null?p.getFileName():store.root().relativize(p)).toString());l.setBorder(BorderFactory.createEmptyBorder(0,8,0,8));l.setFont(Theme.font(13));if(!selected)l.setBackground(Theme.SIDEBAR);return l;}});sidebar.setFixedCellHeight(36);sidebar.setBackground(Theme.SIDEBAR);sidebar.getAccessibleContext().setAccessibleName("Markdown notes");sidebar.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&!refreshing&&sidebar.getSelectedValue()!=null)open(sidebar.getSelectedValue(),false);});sidebar.addMouseListener(new MouseAdapter(){public void mousePressed(MouseEvent e){popup(e);}public void mouseReleased(MouseEvent e){popup(e);}private void popup(MouseEvent e){if(!e.isPopupTrigger())return;int index=sidebar.locationToIndex(e.getPoint());if(index<0)return;sidebar.setSelectedIndex(index);JPopupMenu menu=new JPopupMenu();item(menu,"Open beside",()->open(sidebar.getSelectedValue(),true));item(menu,"Rename note…",()->rename(sidebar.getSelectedValue()));item(menu,"Move to deleted notes",()->delete(sidebar.getSelectedValue()));menu.show(sidebar,e.getX(),e.getY());}});
        sidebar.setDragEnabled(true);sidebar.setTransferHandler(new TransferHandler(){protected Transferable createTransferable(JComponent c){return new StringSelection(sidebar.getSelectedValue().toString());}public int getSourceActions(JComponent c){return COPY;}});
        JScrollPane scroll=new JScrollPane(sidebar);scroll.setBorder(null);library.add(scroll);JPanel bottom=new JPanel(new GridLayout(0,1,0,6));bottom.setOpaque(false);bottom.add(Theme.button("Open folder…",this::chooseFolder));bottom.add(Theme.button("Deleted notes…",this::deletedNotes));library.add(bottom,BorderLayout.SOUTH);
        search.getDocument().addDocumentListener(new DocumentListener(){public void insertUpdate(DocumentEvent e){refresh();}public void removeUpdate(DocumentEvent e){refresh();}public void changedUpdate(DocumentEvent e){refresh();}});
    }
    private void buildPages(){JPanel toolbar=new JPanel(new FlowLayout(FlowLayout.LEFT,4,8));toolbar.setBorder(BorderFactory.createMatteBorder(0,0,1,0,Theme.LINE));toolbar.add(Theme.button("Sidebar",()->{boolean visible=library.isVisible();library.setVisible(!visible);layout.setDividerLocation(visible?0:230);}));JButton style=Theme.button("Style",()->{});style.addActionListener(e->{JPopupMenu m=new JPopupMenu();String[][] kinds={{"Text","paragraph"},{"Heading 1","heading"},{"Heading 2","heading"},{"Heading 3","heading"},{"Bullet list","bullet"},{"Numbered list","ordered"},{"Checklist","task"},{"Quote","quote"},{"Code block","code"}};for(String[] k:kinds)item(m,k[0],()->{if(active!=null)active.block(k[1],k[0].startsWith("Heading")?Integer.parseInt(k[0].substring(8)):1);});m.show(style,0,style.getHeight());});toolbar.add(style);
        for(String kind:List.of("Bold","Italic","Code"))toolbar.add(Theme.button(kind,()->{if(active!=null)active.toggle(kind.toLowerCase(Locale.ROOT));}));toolbar.add(Theme.button("Link",()->{if(active!=null)active.link();}));toolbar.add(Theme.button("Side by side",this::openBeside));pages.add(toolbar,BorderLayout.NORTH);pages.add(left);JPanel footer=new JPanel(new BorderLayout());footer.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(1,0,0,0,Theme.LINE),BorderFactory.createEmptyBorder(10,18,10,18)));status.setFont(Theme.font(12));status.setForeground(Theme.MUTED);count.setFont(Theme.font(12));count.setForeground(Theme.MUTED);footer.add(status);footer.add(count,BorderLayout.EAST);pages.add(footer,BorderLayout.SOUTH);
        for(JTabbedPane tabs:List.of(left,right)){tabs.addChangeListener(e->SwingUtilities.invokeLater(()->{WritingPane p=pane(tabs.getSelectedComponent());if(p!=null){active=p;updateCount();}}));tabs.setTransferHandler(new TransferHandler(){public boolean canImport(TransferSupport s){return s.isDataFlavorSupported(DataFlavor.stringFlavor)||s.isDataFlavorSupported(DataFlavor.javaFileListFlavor);}public boolean importData(TransferSupport s){if(!canImport(s))return false;try{Path path;if(s.isDataFlavorSupported(DataFlavor.javaFileListFlavor)){List<?> f=(List<?>)s.getTransferable().getTransferData(DataFlavor.javaFileListFlavor);path=((File)f.getFirst()).toPath();if(!path.toAbsolutePath().normalize().startsWith(store.root())){importFile(path);return true;}}else path=Path.of((String)s.getTransferable().getTransferData(DataFlavor.stringFlavor));boolean beside=tabs==right||(s.isDrop()&&s.getDropLocation().getDropPoint().x>tabs.getWidth()*.7);open(path,beside);return true;}catch(Exception e){error(e);return false;}}});}
    }
    private JMenuBar menu(){JMenuBar bar=new JMenuBar();JMenu file=new JMenu("File"),edit=new JMenu("Edit"),view=new JMenu("View"),help=new JMenu("Help");bar.add(file);bar.add(edit);bar.add(view);bar.add(help);menuItem(file,"New note",KeyEvent.VK_N,0,this::newNote);menuItem(file,"Open folder…",KeyEvent.VK_O,0,this::chooseFolder);item(file,"Import Markdown…",()->{JFileChooser c=new JFileChooser();c.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Markdown notes","md","markdown"));if(c.showOpenDialog(frame)==JFileChooser.APPROVE_OPTION)importFile(c.getSelectedFile().toPath());});menuItem(file,"Save all",KeyEvent.VK_S,0,()->saveAll(false));item(file,"Export active note…",this::export);menuItem(file,"Rename note…",KeyEvent.VK_R,InputEvent.SHIFT_DOWN_MASK,()->{Session s=current();if(s!=null)rename(s.path);});item(file,"Move note to deleted notes",()->{Session s=current();if(s!=null)delete(s.path);});item(file,"Restore last deleted note",this::restoreLast);item(file,"Deleted notes…",this::deletedNotes);menuItem(file,"Close note",KeyEvent.VK_W,0,()->{JTabbedPane t=activeTabs();if(t.getSelectedIndex()>=0)closeTab(t,t.getSelectedIndex());});
        menuItem(edit,"Undo",KeyEvent.VK_Z,0,()->{Session s=current();if(s!=null&&s.undo.canUndo())s.undo.undo();});menuItem(edit,"Redo",KeyEvent.VK_Z,InputEvent.SHIFT_DOWN_MASK,()->{Session s=current();if(s!=null&&s.undo.canRedo())s.undo.redo();});menuItem(edit,"Find in note…",KeyEvent.VK_F,0,this::find);menuItem(view,"Side by side",KeyEvent.VK_BACK_SLASH,0,this::openBeside);item(view,"Single pane",this::singlePane);item(help,"Keyboard shortcuts",()->JOptionPane.showMessageDialog(frame,"⌘N  New note\n⌘O  Open folder\n⌘S  Save\n⌘W  Close tab\n⌘B / ⌘I  Bold / italic\n⌘F  Find in note\n⌘Z / ⇧⌘Z  Undo / redo\n⌘\\  Side by side\n\nType / on an empty line for blocks.\nType # then Space for a heading.\nDouble-click a checklist line to toggle it.","Writing shortcuts",JOptionPane.PLAIN_MESSAGE));item(help,"About diyalamp",this::about);return bar;}
    private void setFolder(Path root)throws IOException {store=new NoteStore(root);folderName.setText(store.root().getFileName().toString());folderName.setToolTipText(store.root().toString());preferences.put("folder",store.root().toString());frame.setTitle("diyalamp · "+store.root().getFileName());}
    private void chooseFolder(){if(!saveAll(true))return;JFileChooser c=new JFileChooser(store.root().toFile());c.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(c.showOpenDialog(frame)!=JFileChooser.APPROVE_OPTION)return;try{setFolder(c.getSelectedFile().toPath());sessions.clear();left.removeAll();right.removeAll();active=null;singlePane();refresh();if(!files.isEmpty())open(files.firstElement(),false);}catch(Exception e){error(e);}}
    private void refresh(){if(store==null)return;try{Path selected=sidebar.getSelectedValue();String q=search.getText().strip().toLowerCase(Locale.ROOT);refreshing=true;files.clear();for(Path p:store.notes())if(p.getFileName().toString().toLowerCase(Locale.ROOT).contains(q))files.addElement(p);sidebar.setSelectedValue(selected,true);}catch(Exception e){error(e);}finally{refreshing=false;}}
    private void newNote(){try{Path p=store.create("Untitled","# Untitled\n\n");refresh();open(p,false);if(active!=null){active.setCaretPosition(0);active.moveCaretPosition(8);active.requestFocusInWindow();}}catch(Exception e){error(e);}}
    private void open(Path path,boolean beside){if(path==null)return;try{Session s=sessions.get(path);if(s==null){s=new Session(path,store.load(path));sessions.put(path,s);}JTabbedPane target=beside?right:left;if(beside)ensureSplit();for(int i=0;i<target.getTabCount();i++)if(target.getComponentAt(i) instanceof JScrollPane scroll&&scroll.getClientProperty("session")==s){target.setSelectedIndex(i);active=(WritingPane)scroll.getViewport().getView();active.requestFocusInWindow();return;}
            Session note=s;boolean firstView=note.viewCount++==0;note.loadingViews++;WritingPane editor=new WritingPane(note.document,()->{if(note.loadingViews>0)return;String next=Markdown.write(note.document);if(next.equals(note.serialized))return;note.dirty=true;note.error=false;status.setText("Saving…");autosave.restart();updateCount();});editor.addFocusListener(new FocusAdapter(){public void focusGained(FocusEvent e){active=editor;updateCount();}});JScrollPane scroll=new JScrollPane(editor);scroll.putClientProperty("session",note);scroll.setBorder(null);scroll.getVerticalScrollBar().setUnitIncrement(18);target.addTab(note.path.getFileName().toString(),scroll);target.setTabComponentAt(target.indexOfComponent(scroll),tabHeader(note,target,scroll));target.setSelectedComponent(scroll);active=editor;editor.requestFocusInWindow();updateCount();SwingUtilities.invokeLater(()->{if(!note.dirty)note.serialized=Markdown.write(note.document);note.loadingViews--;if(firstView)note.undo.discardAllEdits();});
        }catch(Exception e){error(e);}}
    private JPanel tabHeader(Session s,JTabbedPane target,Component page){JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));p.setOpaque(false);JLabel title=new JLabel(s.path.getFileName().toString());title.setFont(Theme.font(13));p.add(title);JButton close=new JButton("×");close.setBorder(BorderFactory.createEmptyBorder(2,3,2,3));close.setContentAreaFilled(false);close.setFocusable(false);close.getAccessibleContext().setAccessibleName("Close "+s.path.getFileName());close.addActionListener(e->closeTab(target,target.indexOfComponent(page)));p.add(close);return p;}
    private void closeTab(JTabbedPane t,int index){if(index<0)return;if(!saveAll(true))return;t.remove(index);if(right.getTabCount()==0)singlePane();active=pane(activeTabs().getSelectedComponent());updateCount();}
    private WritingPane pane(Component c){return c instanceof JScrollPane s&&s.getViewport().getView() instanceof WritingPane p?p:null;}
    private JTabbedPane activeTabs(){return active!=null&&SwingUtilities.isDescendingFrom(active,right)?right:left;}
    private Session current(){if(active==null)return null;return sessions.values().stream().filter(s->s.document==active.getDocument()).findFirst().orElse(null);}
    private void ensureSplit(){if(split!=null)return;pages.remove(left);split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,left,right);split.setResizeWeight(.5);split.setDividerSize(1);split.setBorder(null);pages.add(split);pages.revalidate();SwingUtilities.invokeLater(()->split.setDividerLocation(.5));}
    private void singlePane(){if(split==null)return;pages.remove(split);split=null;right.removeAll();pages.add(left);pages.revalidate();pages.repaint();active=pane(left.getSelectedComponent());}
    private void openBeside(){Path next=null;Session s=current();for(int i=0;i<files.size();i++)if(s==null||!files.get(i).equals(s.path)){next=files.get(i);break;}if(next==null&&s!=null)next=s.path;if(next!=null)open(next,true);}
    private boolean saveAll(boolean show){boolean ok=true;for(Session s:sessions.values())if(s.dirty){try{String text=Markdown.write(s.document);s.fingerprint=store.save(s.path,text,s.fingerprint);s.serialized=text;s.dirty=false;s.error=false;}catch(Exception e){ok=false;status.setForeground(Theme.RED);status.setText("Not saved · "+s.path.getFileName()+" · export a copy to keep your edits");if(show)error(e);s.error=true;}}if(ok){status.setForeground(Theme.MUTED);status.setText("All changes saved · local files");}return ok;}
    private void rename(Path p){if(p==null||!saveAll(true))return;String name=JOptionPane.showInputDialog(frame,"Note name",p.getFileName().toString().replaceFirst("(?i)\\.(md|markdown)$",""));if(name==null)return;try{Path renamed=store.rename(p,name);Session s=sessions.remove(p);if(s!=null){s.path=renamed;sessions.put(renamed,s);for(JTabbedPane t:List.of(left,right))for(int i=0;i<t.getTabCount();i++)if(t.getComponentAt(i) instanceof JScrollPane scroll&&scroll.getClientProperty("session")==s){t.setTitleAt(i,renamed.getFileName().toString());t.setTabComponentAt(i,tabHeader(s,t,scroll));}}refresh();sidebar.setSelectedValue(renamed,true);}catch(Exception e){error(e);}}
    private void delete(Path p){if(p==null||!saveAll(true))return;try{lastDeleted=store.trash(p);Session deleted=sessions.remove(p);for(JTabbedPane t:List.of(left,right))for(int i=t.getTabCount()-1;i>=0;i--)if(t.getComponentAt(i) instanceof JScrollPane scroll&&scroll.getClientProperty("session")==deleted)t.remove(i);if(right.getTabCount()==0)singlePane();refresh();active=pane(left.getSelectedComponent());status.setText("Moved to deleted notes · File → Restore last deleted note");}catch(Exception e){error(e);}}
    private void restoreLast(){if(lastDeleted==null)return;try{Path p=store.restore(lastDeleted);lastDeleted=null;refresh();open(p,false);}catch(Exception e){error(e);}}
    private void deletedNotes(){try{Path trash=store.root().resolve(".diyalamp-trash");Files.createDirectories(trash);JFileChooser c=new JFileChooser(trash.toFile());c.setDialogTitle("Restore a deleted Markdown note");if(c.showDialog(frame,"Restore note")==JFileChooser.APPROVE_OPTION){Path chosen=c.getSelectedFile().toPath().toRealPath();if(!chosen.getParent().equals(trash.toRealPath())||!NoteStore.isMarkdown(chosen))throw new IOException("Choose a deleted Markdown note from this folder.");String name=chosen.getFileName().toString().replaceFirst("^\\d+-[a-f0-9-]{36}-","");Path target=store.unique(name);Files.move(chosen,target);refresh();open(target,false);}}catch(Exception e){error(e);}}
    private void importFile(Path path){try{if(!NoteStore.isMarkdown(path)||Files.size(path)>NoteStore.MAX_BYTES)throw new IOException("Choose a Markdown file smaller than 5 MB.");Path copy=store.create(path.getFileName().toString(),Files.readString(path));refresh();open(copy,false);}catch(Exception e){error(e);}}
    private void export(){Session s=current();if(s==null)return;JFileChooser c=new JFileChooser();c.setSelectedFile(s.path.getFileName().toFile());if(c.showSaveDialog(frame)!=JFileChooser.APPROVE_OPTION)return;Path target=c.getSelectedFile().toPath();if(Files.exists(target)&&JOptionPane.showConfirmDialog(frame,"Replace this exported file?","Export note",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{Files.writeString(target,Markdown.write(s.document));status.setText("Exported a Markdown copy");}catch(Exception e){error(e);}}
    private void find(){if(active==null)return;String query=JOptionPane.showInputDialog(frame,"Find in this note");if(query==null||query.isEmpty())return;try{String text=active.getDocument().getText(0,active.getDocument().getLength());int start=text.toLowerCase(Locale.ROOT).indexOf(query.toLowerCase(Locale.ROOT),active.getSelectionEnd());if(start<0)start=text.toLowerCase(Locale.ROOT).indexOf(query.toLowerCase(Locale.ROOT));if(start>=0){active.requestFocusInWindow();active.select(start,start+query.length());}else status.setText("No match in this note");}catch(BadLocationException ignored){}}
    private void updateCount(){if(active==null){count.setText(" ");return;}try{String text=active.getDocument().getText(0,active.getDocument().getLength()).strip();count.setText((text.isEmpty()?0:text.split("\\s+").length)+" words");}catch(BadLocationException ignored){}}
    private void about(){JOptionPane.showMessageDialog(frame,"diyalamp "+VERSION+"\nA tool for the mind.\n\nOpen source. Local Markdown files.\nhttps://diyalamp.com\nApache License 2.0","About diyalamp",JOptionPane.PLAIN_MESSAGE,Theme.lamp(64));}
    private void error(Exception e){JOptionPane.showMessageDialog(frame,e.getMessage(),"Your writing stays open",JOptionPane.ERROR_MESSAGE);}
    private static void item(JComponent m,String text,Runnable r){JMenuItem i=new JMenuItem(text);i.addActionListener(e->r.run());m.add(i);}
    private static void menuItem(JComponent m,String text,int key,int mods,Runnable r){JMenuItem i=new JMenuItem(text);i.setAccelerator(KeyStroke.getKeyStroke(key,Toolkit.getDefaultToolkit().getMenuShortcutKeyMaskEx()|mods));i.addActionListener(e->r.run());m.add(i);}
    private static String welcome(){return "# A little light for your thoughts\n\nWelcome to **diyalamp**. This is your quiet place to write, think, and keep what matters.\n\n## Make yourself at home\n\n- Create a note from the sidebar.\n- Type / on an empty line to choose a block.\n- Use **bold**, *italic*, and `inline code` as you write.\n- Open a second note with **Side by side**.\n\n> Your words stay in ordinary Markdown files, in a folder you control.\n\n## A small writing ritual\n\n- [ ] Capture one idea.\n- [ ] Give it room to grow.\n- [ ] Keep on keeping on.\n\nNo account. No subscription. Just a little space to think.\n";}
}
